            return (f - 32.0) * 5.0 / 9.0;
        }
    }

    public static void main(String[] args) {
        double f = TemperatureConverter.celsiusToFahrenheit(100.0);
        double c = TemperatureConverter.fahrenheitToCelsius(212.0);
