public class Solution {
    static class ComplexNumber {
        private final double real;
        private final double imag;

        private ComplexNumber(double real, double imag) {
            this.real = real;
            this.imag = imag;
        }

        public static ComplexNumber fromCartesian(double real, double imag) {
            return new ComplexNumber(real, imag);
        }

        public static ComplexNumber fromPolar(double r, double theta) {
            return new ComplexNumber(r * Math.cos(theta), r * Math.sin(theta));
        }

        public String toString() {
            return String.format("%.2f + %.2fi", real, imag);
        }
    }

    public static void main(String[] args) {
        ComplexNumber c1 = ComplexNumber.fromCartesian(3.0, 4.0);
        ComplexNumber c2 = ComplexNumber.fromPolar(5.0, Math.PI / 4);
        System.out.println("Cartesian: " + c1);
        System.out.println("Polar:     " + c2);
    }
}

