import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    static class IdFactory {
        private static int counter = 0;

        public static synchronized int generateId() {
            return ++counter;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Set<Integer> idSet = Collections.synchronizedSet(new HashSet<>());
        Thread t1 = new Thread(() -> { for (int i = 0; i < 500; i++) idSet.add(IdFactory.generateId()); });
        Thread t2 = new Thread(() -> { for (int i = 0; i < 500; i++) idSet.add(IdFactory.generateId()); });

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Total generated unique IDs: " + idSet.size());
    }
}

