import java.util.Arrays;
import java.util.List;

public class Solution {
    public static <T extends Comparable<T>> T findMax(List<T> list) {
        if (list == null || list.isEmpty()) {
            throw new IllegalArgumentException("List cannot be empty");
        }
        T max = list.get(0);
        for (T item : list) {
            if (item.compareTo(max) > 0) {
                max = item;
            }
        }
        return max;
    }

    public static void main(String[] args) {
        List<Integer> intList = Arrays.asList(4, 92, 15, 33);
        List<String> strList = Arrays.asList("Apple", "Zebra", "Mango");

        System.out.println("Max integer: " + findMax(intList));
        System.out.println("Max string:  " + findMax(strList));
    }
}

import java.util.LinkedHashMap;
import java.util.Map;

public class Solution {
    static class BoundedCache<K, V> extends LinkedHashMap<K, V> {
        private final int maxCapacity;

        public BoundedCache(int capacity) {
            super(capacity, 0.75f, true);
            this.maxCapacity = capacity;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > maxCapacity; // Evict eldest entry when capacity is exceeded
        }
    }

    public static void main(String[] args) {
        BoundedCache<String, String> cache = new BoundedCache<>(2);
        cache.put("A", "Alpha");
        cache.put("B", "Beta");
        cache.put("C", "Gamma"); // Causes "A" to be evicted

        System.out.println("Cache contents: " + cache);
        System.out.println("Contains evicted key 'A': " + cache.containsKey("A"));
    }
}

