import java.util.function.LongSupplier;

public class Solution {
    static class TokenService {
        private final LongSupplier clock;

        public TokenService() {
            this(System::currentTimeMillis); // Production default
        }

        public TokenService(LongSupplier clock) {
            this.clock = clock; // Injected dependency for testing
        }

        public boolean isExpired(long tokenTimestamp, long ttlMs) {
            return clock.getAsLong() > (tokenTimestamp + ttlMs);
        }
    }

    public static void main(String[] args) {
        // Simulated test with fixed timestamp
        LongSupplier mockClock = () -> 1000000L;
        TokenService service = new TokenService(mockClock);

        boolean expired = service.isExpired(900000L, 50000L); // 950000 < 1000000 -> expired
        System.out.println("Is token expired at mock time: " + expired);
    }
}

public class Solution {
    static class DatabaseConnection {
        private static volatile DatabaseConnection instance;
        private String status;

        private DatabaseConnection() {
            this.status = "Connected to Database";
        }

        public static DatabaseConnection getInstance() {
            if (instance == null) {
                synchronized (DatabaseConnection.class) {
                    if (instance == null) {
                        instance = new DatabaseConnection();
                    }
                }
            }
            return instance;
        }

        public String getStatus() {
            return status;
        }
    }

    public static void main(String[] args) {
        DatabaseConnection c1 = DatabaseConnection.getInstance();
        DatabaseConnection c2 = DatabaseConnection.getInstance();
        System.out.println("Singleton identity check: " + (c1 == c2));
        System.out.println("Status: " + c1.getStatus());
    }
}

